import{_ as e,a as o}from"./chunks/crd-code.CuKzBF2I.js";import{_ as a,o as r,c as s,a5 as n}from"./chunks/framework.BYXPg_yw.js";const b=JSON.parse('{"title":"Remote Support","description":"","frontmatter":{"layout":"doc","outline":"deep","title":"Remote Support"},"headers":[],"relativePath":"manual/support/remote.md","filePath":"manual/support/remote.md","lastUpdated":1793350928000}'),i={name:"manual/support/remote.md"};function h(l,t,p,d,c,m){return r(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="remote-support-chrome-remote-desktop" tabindex="-1">Remote support (Chrome Remote Desktop) <a class="header-anchor" href="#remote-support-chrome-remote-desktop" aria-label="Permalink to &quot;Remote support (Chrome Remote Desktop)&quot;">​</a></h1><p>To ask for remote support, email <strong><a href="mailto:rbq.support@rainbow-robotics.com" target="_blank" rel="noreferrer">rbq.support@rainbow-robotics.com</a></strong>. The support team contacts you separately to set a time.</p><p>In remote support, you open one laptop on site to the team through <strong>Chrome Remote Desktop</strong>. The support engineer reaches the robot through that laptop. The steps run in order: <strong>prepare a laptop → connect it to the robot → install the program → hand over the access code.</strong></p><div class="danger custom-block"><p class="custom-block-title">⚠ Someone must stay by the robot during remote support</p><p>The engineer may restart the robot software or move the robot remotely. Until support ends, <strong>keep the area around the robot clear</strong> and keep one person beside it, ready to stop it at any time. See <a href="/RBQ/nightly/guides/common/emo.html">Emergency stop and recovery</a>.</p></div><h2 id="what-you-need" tabindex="-1">1. What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;1. What you need {#what-you-need}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Laptop</strong></td><td>Windows, macOS or Ubuntu, with the <strong>Chrome browser</strong></td></tr><tr><td><strong>Internet</strong></td><td>The route the support team uses to reach the laptop</td></tr><tr><td><strong>Robot network</strong></td><td>The robot&#39;s Wi-Fi (name starting with <code>RBQ_</code>) or a LAN cable into the switch hub</td></tr><tr><td><strong>Google account</strong></td><td>Needed to install Chrome Remote Desktop</td></tr><tr><td><strong>Person on site</strong></td><td>Someone at the laptop and by the robot, reachable by phone</td></tr></tbody></table><h2 id="connect-laptop" tabindex="-1">2. Connect the laptop to the robot and the internet <a class="header-anchor" href="#connect-laptop" aria-label="Permalink to &quot;2. Connect the laptop to the robot and the internet {#connect-laptop}&quot;">​</a></h2><p>The laptop has to be on <strong>the robot network and the internet at the same time</strong>. With only one of them, the support team can reach the laptop but not the robot.</p><table tabindex="0"><thead><tr><th>Robot</th><th>How to connect</th></tr></thead><tbody><tr><td><strong>Has an LTE/5G module</strong></td><td>The robot&#39;s Wi-Fi covers both</td></tr><tr><td><strong>No LTE/5G module</strong></td><td>Plug a <strong>LAN cable</strong> into the robot&#39;s switch hub, and take the internet from <strong>another Wi-Fi</strong> or a phone hotspot</td></tr></tbody></table><p>Once connected, check that the laptop reaches the robot&#39;s motion PC.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Command Prompt on Windows, Terminal on macOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ping</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.0.10</span></span></code></pre></div><p>Replies mean it works. With no reply, check the robot&#39;s layout on <a href="/RBQ/nightly/manual/interface/network.html">Network diagram</a> and make sure the laptop&#39;s address is in the <code>192.168.0.x</code> range.</p><div class="warning custom-block"><p class="custom-block-title">⚠ Keep the laptop awake</p><p>Sleep or screen lock drops the remote connection. During support, <strong>keep it plugged in</strong>, turn off sleep, and leave the lid open.</p></div><h2 id="install" tabindex="-1">3. Install Chrome Remote Desktop <a class="header-anchor" href="#install" aria-label="Permalink to &quot;3. Install Chrome Remote Desktop {#install}&quot;">​</a></h2><ol><li>In Chrome on the laptop, open <strong><a href="https://remotedesktop.google.com/support" target="_blank" rel="noreferrer">remotedesktop.google.com/support</a></strong>.</li><li>Sign in with a Google account.</li><li>When the <strong>Install Chrome Remote Desktop?</strong> prompt appears at the bottom right, press <strong>Install</strong>.</li><li>Press the download button on the <strong>Share this screen</strong> card under <strong>This device</strong>, and install the extension and the installer as prompted.</li><li>When the install finishes, a <strong>Generate Code</strong> button appears on the same card.</li></ol><figure><img src="`+e+`" alt="Chrome Remote Desktop — the Share this screen card and the install prompt at the bottom right"><figcaption style="text-align:center;">[ Install from the bottom-right prompt → download button on the Share this screen card ]</figcaption></figure><p>You install it once. From the next remote support on, start at step 5.</p><h3 id="install-ubuntu" tabindex="-1">Installing on an Ubuntu laptop <a class="header-anchor" href="#install-ubuntu" aria-label="Permalink to &quot;Installing on an Ubuntu laptop {#install-ubuntu}&quot;">​</a></h3><p>On Ubuntu, the download button in step 4 saves a <code>.deb</code> file. Install it from a terminal.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Downloads</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./chrome-remote-desktop_current_amd64.deb</span></span></code></pre></div><p>When it finishes, <strong>reload</strong> the Chrome page. A <strong>Generate Code</strong> button on the <strong>Share this screen</strong> card means it is installed. For details, see <strong>Use Chrome Remote Desktop on Linux</strong> in Google&#39;s official guide (<a href="https://support.google.com/chrome/answer/1649523?hl=en" target="_blank" rel="noreferrer">Chrome Remote Desktop help</a>).</p><h2 id="share-code" tabindex="-1">4. Hand over the access code <a class="header-anchor" href="#share-code" aria-label="Permalink to &quot;4. Hand over the access code {#share-code}&quot;">​</a></h2><ol><li><p><strong>While on the phone with the support team</strong>, press <strong>Generate Code</strong>.</p></li><li><p>Read the <strong>12-digit number</strong> on screen to the support team.</p><figure><img src="`+o+'" alt="Chrome Remote Desktop — the 12-digit access code on the Share this screen card"><figcaption style="text-align:center;">[ The 12-digit access code and the time left ]</figcaption></figure></li><li><p>When the team asks to connect, a confirmation appears on the laptop. Check the email address shown and press <strong>Share</strong>.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">📝 The code is valid for 5 minutes</p><p>After that it disappears. Generate it once the team is ready to take it, and press <strong>Generate Code</strong> again if it expires. A code works only once.</p></div><h2 id="during" tabindex="-1">5. During remote support <a class="header-anchor" href="#during" aria-label="Permalink to &quot;5. During remote support {#during}&quot;">​</a></h2><ul><li><strong>Do not touch the laptop&#39;s mouse or keyboard.</strong> Input from both sides gets mixed.</li><li><strong>Do not drive the robot from the app</strong> unless the support team asks you to.</li><li><strong>Every 30 minutes</strong> the laptop <strong>asks whether to keep sharing</strong>. If the team is still working, choose to continue. With no answer, the connection drops.</li><li>If the team says it will sit or restart the robot, check that nobody is near it and tell them.</li></ul><h2 id="finish" tabindex="-1">6. Finish <a class="header-anchor" href="#finish" aria-label="Permalink to &quot;6. Finish {#finish}&quot;">​</a></h2><ol><li>When the team says it is done, press <strong>Stop Sharing</strong> on the laptop.</li><li>Start the robot again as the team instructs and check that it behaves normally.</li></ol><p>Once sharing stops, the team can no longer reach the laptop. Next time needs a new code.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also {#see-also}&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/manual/support/">Requesting support</a> — file the symptom and logs before remote support</li><li><a href="https://support.google.com/chrome/answer/1649523?hl=en" target="_blank" rel="noreferrer">Chrome Remote Desktop help</a> — Google&#39;s official guide (install, screen sharing, Linux)</li><li><a href="/RBQ/nightly/manual/interface/network.html">Network diagram</a> — the robot&#39;s addresses and connection layout</li><li><a href="/RBQ/nightly/guides/common/emo.html">Emergency stop and recovery</a></li></ul>',31)])])}const k=a(i,[["render",h]]);export{b as __pageData,k as default};
